  ), changed as (
    update public.recipes r
    set serving_style = reviewed.style,
        source_brew_parameters = jsonb_set(coalesce(r.source_brew_parameters, '{}'::jsonb), '{discovery}',
          coalesce(r.source_brew_parameters->'discovery', '{}'::jsonb) ||
          jsonb_build_object('serving_style', reviewed.style, 'serving_style_evidence',
            jsonb_build_object('classification', reviewed.classification, 'basis', reviewed.basis,
              'source_title', reviewed.source_title, 'reviewed_at', '2026-10-06',
              'requires_source_confirmation', reviewed.classification = 'inferred',
              'rule_version', 'serving_completion_v1')), true)
    from reviewed
    where r.id = reviewed.id and r.title = reviewed.source_title
      and r.brew_method = reviewed.method and r.visibility = 'public'
      and md5(r.source_brew_parameters::text) = reviewed.source_hash
      and coalesce(r.serving_style, 'unknown') not in ('hot','iced','cold')
      and coalesce(r.source_brew_parameters#>>'{discovery,serving_style}', 'unknown') not in ('hot','iced','cold')
    returning r.id
  ) select count(*) into changed_count from changed;
  if changed_count <> 2875 then
    raise exception 'Serving completion snapshot changed: expected 2875 matched recipes, got %', changed_count;
  end if;
end $completion$;
